HTML = r'''<!doctype html>
<html>
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<title>ClipForge</title>
<style>
*{box-sizing:border-box}body{margin:0;background:#090a0f;color:#f7f7fb;font:15px system-ui,-apple-system,Segoe UI,sans-serif}
main{max-width:1180px;margin:auto;padding:32px 18px 90px}.hero{padding:48px 0 24px}.tag{font-size:12px;font-weight:900;letter-spacing:.14em;color:#9f7aea}
h1{font-size:clamp(44px,9vw,82px);line-height:.94;margin:12px 0}h1 span{color:#9b6cff}h2{margin:0 0 8px;font-size:19px}
p{color:#a5a9b8;line-height:1.6}.card{margin:16px 0;padding:22px;border:1px solid #2b2f3d;border-radius:18px;background:#12141b}
.row{display:flex;gap:10px;align-items:center;flex-wrap:wrap}.btn,button{border:0;border-radius:11px;padding:12px 16px;background:#835dff;color:white;font-weight:850;text-decoration:none;cursor:pointer}
.secondary{background:#242733}.ghost{background:transparent;border:1px solid #3a4050}.danger{background:#612a34}.pill{border:1px solid #343948;border-radius:999px;padding:8px 11px;color:#adb2c2;font-size:12px}
code{display:block;padding:12px;background:#0c0e13;border:1px solid #292d3a;border-radius:9px;overflow:auto}input{background:#0d0f15;color:#fff;border:1px solid #333847;border-radius:10px;padding:11px 12px;font:inherit}
input[type=text]{min-width:240px;flex:1}input[type=number]{width:92px}.clips{display:grid;gap:11px;margin-top:15px}.clip{display:grid;grid-template-columns:1fr auto auto;gap:12px;align-items:center;padding:15px;border:1px solid #2e3342;background:#191c25;border-radius:13px}
.score{font-size:25px;font-weight:900;color:#5ce6a5}.small{font-size:12px;color:#9299aa}.creator{color:#b8a6ff;font-weight:800}.hidden{display:none!important}.warn{color:#ffd274}.selected{outline:2px solid #835dff}
.editorItem{padding:14px;border:1px solid #343949;background:#171a22;border-radius:14px;margin:10px 0}.editorItem.previewing{border-color:#835dff;box-shadow:0 0 0 1px #835dff inset}.grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:10px}.grid label{font-size:12px;color:#9da3b3}.grid input{width:100%;margin-top:5px}
.download{display:inline-block;margin-top:12px}.tabs{display:flex;gap:8px;margin:6px 0 20px;padding:6px;background:#11131a;border:1px solid #2b2f3d;border-radius:15px;position:sticky;top:10px;z-index:20;backdrop-filter:blur(12px)}
.tab{flex:1;background:transparent;color:#aeb3c2;border:1px solid transparent;padding:13px 16px}.tab.active{background:#242733;color:white;border-color:#3b4152}.tabBadge{margin-left:7px;background:#835dff;border-radius:999px;padding:2px 7px;font-size:11px;color:white}.tabPanel{display:none}.tabPanel.active{display:block}.editorHero{display:flex;gap:16px;align-items:flex-start;justify-content:space-between}.editorHero p{margin:4px 0 0}.emptyEditor{text-align:center;padding:46px 18px;border:1px dashed #3a4050;border-radius:16px;color:#9299aa}
.editorWorkspace{display:grid;grid-template-columns:minmax(0,1fr) 350px;gap:22px;align-items:start}.editorControls{min-width:0}.previewColumn{position:sticky;top:90px}.previewLabel{display:flex;align-items:center;justify-content:space-between;margin:0 0 10px}.previewLabel b{font-size:14px}.phoneShell{width:330px;max-width:100%;margin:auto;background:#050505;border:1px solid #32343c;border-radius:38px;padding:8px;box-shadow:0 24px 70px #0008}.phoneScreen{height:640px;max-height:78vh;min-height:540px;position:relative;overflow:hidden;border-radius:31px;background:#000;color:white}.phoneMedia,.phoneThumb,.demoCanvas{position:absolute;inset:0;width:100%;height:100%;object-fit:contain;background:#000}.demoCanvas{display:flex;align-items:center;justify-content:center;background:radial-gradient(circle at 60% 35%,#3b2f68 0,#171723 35%,#050505 72%);font-size:13px;font-weight:900;letter-spacing:.12em;color:#bdaeff}.phoneTop{position:absolute;z-index:7;top:17px;left:16px;right:16px;display:flex;align-items:center;justify-content:space-between;font-size:12px;font-weight:800;text-shadow:0 1px 5px #000}.phoneTabs{position:absolute;z-index:7;top:22px;left:50%;transform:translateX(-50%);display:flex;gap:18px;font-size:12px}.phoneTabs span:first-child{color:#9b9b9b}.phoneTabs span:last-child{font-weight:900;border-bottom:2px solid white;padding-bottom:6px}.previewHook{position:absolute;z-index:6;top:88px;left:26px;right:26px;text-align:center;font-weight:950;font-size:21px;line-height:1.05;text-transform:uppercase;text-shadow:0 2px 8px #000,0 0 2px #000}.phoneRail{position:absolute;z-index:7;right:10px;bottom:76px;width:43px;display:grid;gap:17px;text-align:center}.railIcon{font-size:25px;line-height:1}.railText{font-size:8px;font-weight:700;margin-top:3px;text-shadow:0 1px 4px #000}.phoneMeta{position:absolute;z-index:7;left:13px;right:58px;bottom:61px;text-shadow:0 1px 5px #000}.phoneMeta b{font-size:12px}.phoneMeta div{font-size:10px;line-height:1.35;margin-top:5px}.phoneMeta .audio{white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.phoneBottom{position:absolute;z-index:8;bottom:0;left:0;right:0;height:50px;background:linear-gradient(transparent,#000 24%);display:flex;align-items:flex-end;justify-content:space-around;padding:0 8px 8px;font-size:8px}.phoneNavItem{text-align:center;min-width:35px}.phoneNavIcon{font-size:17px;display:block;margin-bottom:2px}.phoneCreate{font-size:19px;background:white;color:#111;border-radius:7px;padding:0 9px;box-shadow:-4px 0 #2bd9e5,4px 0 #ff416c}.trimBadge{position:absolute;z-index:8;left:12px;top:54px;background:#000a;border:1px solid #ffffff24;border-radius:999px;padding:5px 8px;font-size:9px}.clipBadge{position:absolute;z-index:8;right:12px;top:54px;background:#000a;border:1px solid #ffffff24;border-radius:999px;padding:5px 8px;font-size:9px}.previewHint{text-align:center;color:#858b9a;font-size:11px;margin-top:9px}.resultCard{margin-top:16px;padding:14px;border:1px solid #343949;border-radius:13px;background:#171a22}
@media(max-width:900px){.editorWorkspace{grid-template-columns:1fr}.previewColumn{position:relative;top:auto;order:-1}.phoneScreen{max-height:none;height:620px}.phoneShell{width:320px}}
@media(max-width:760px){.clip{grid-template-columns:1fr auto}.clip .actions{grid-column:1/3}.grid{grid-template-columns:1fr 1fr}.hero{padding-top:28px}.tabs{top:6px}.editorHero{display:block}}
</style>
</head>
<body><main>
<section class="hero"><div class="tag">TWITCH → CLIP SCOUT → SHORT EDITOR</div><h1>ClipForge <span>Web</span></h1><p>Scout clips, select several moments, then switch to the editor tab to arrange, trim, preview, render, and download your finished Short.</p><div class="row"><a class="btn" href="/auth/twitch">Connect Twitch</a><button class="secondary" onclick="scanMine('demo')">Try demo</button><span class="pill" id="status">Checking…</span></div></section>

<nav class="tabs" aria-label="ClipForge sections">
<button id="clipsTab" class="tab active" onclick="showTab('clips')">Clip Scout</button>
<button id="editorTab" class="tab" onclick="showTab('editor')">Short Editor <span id="tabSelectedCount" class="tabBadge hidden">0</span></button>
</nav>

<section id="clipsPanel" class="tabPanel active">
<div class="card" id="setup"><h2>One-time Twitch setup</h2><p>Add this exact callback URL to your Twitch Developer app, then add TWITCH_CLIENT_ID and TWITCH_CLIENT_SECRET in Render.</p><code id="callback">Loading…</code></div>
<div class="card"><h2>Scout other Twitch channels</h2><p>Enter up to 10 usernames. ClipForge ranks their recent public clips. You can select them for a project, but rendering requires that your connected Twitch account is that broadcaster or an authorized editor.</p><div class="row"><input id="channels" type="text" placeholder="example: shroud, tarik, pokimane"><button onclick="scout()">Scan channels</button></div><div id="scoutClips" class="clips"><p>No channels scanned yet.</p></div></div>
<div class="card"><div class="row"><h2 style="margin-right:auto">My best clips</h2><button onclick="scanMine('live')">Scan my Twitch</button><button class="secondary" onclick="scanMine('demo')">Demo scan</button></div><div id="clips" class="clips"><p>No clips scanned yet.</p></div></div>
<div class="card"><div class="row"><div><b id="selectionSummary">No clips selected</b><div class="small">Select up to 10 clips, then move to the editor.</div></div><button style="margin-left:auto" onclick="showTab('editor')">Edit selected clips →</button></div></div>
</section>

<section id="editorPanel" class="tabPanel">
<div class="card">
<div class="editorHero"><div><h2>Short Editor</h2><p>Edit on the left and watch the vertical social preview update on the right.</p></div><span class="pill" id="selectedCount">0 clips selected</span></div>
<div class="editorWorkspace" style="margin-top:18px">
<div class="editorControls">
<div class="row"><input id="globalHook" type="text" maxlength="60" placeholder="Main hook text, e.g. THIS ESCALATED FAST 💀" oninput="projectChanged()"><button class="secondary" onclick="clearSelection()">Clear all</button><button class="ghost" onclick="showTab('clips')">+ Add more clips</button></div>
<div id="editorList" style="margin-top:16px"><div class="emptyEditor">No clips selected yet.<br><br><button onclick="showTab('clips')">Go select clips</button></div></div>
<div class="row" style="margin-top:16px"><button onclick="renderProject()">Render selected clips</button><span id="renderStatus" class="small"></span></div>
<div id="result" class="hidden resultCard"><b>Export ready</b><div class="small">The rendered MP4 is now playing in the phone preview.</div><a id="downloadBtn" class="btn download" href="#" download="clipforge-short.mp4">Download edited MP4</a></div>
</div>

<aside class="previewColumn">
<div class="previewLabel"><b>Short preview</b><span class="pill" id="previewStatus">Live layout</span></div>
<div class="phoneShell"><div class="phoneScreen" id="phoneScreen">
<div id="demoCanvas" class="demoCanvas">SELECT A CLIP</div>
<img id="phoneThumb" class="phoneThumb hidden" alt="Selected clip preview">
<video id="phoneVideo" class="phoneMedia hidden" controls playsinline></video>
<div class="phoneTop"><span id="phoneTime">8:00</span><span>● ● ●</span></div>
<div class="phoneTabs"><span>Following</span><span>For You</span></div>
<div id="trimBadge" class="trimBadge">0.0s – 0.0s</div><div id="clipBadge" class="clipBadge">0 / 0</div>
<div id="previewHook" class="previewHook hidden"></div>
<div class="phoneRail"><div><div class="railIcon">♡</div><div class="railText">Like</div></div><div><div class="railIcon">●</div><div class="railText">Comment</div></div><div><div class="railIcon">▮</div><div class="railText">Save</div></div><div><div class="railIcon">↗</div><div class="railText">Share</div></div></div>
<div class="phoneMeta"><b id="previewCreator">@clipforge</b><div id="previewCaption">Select a clip to preview your Short.</div><div class="audio">♫ original sound · <span id="previewAudio">ClipForge</span></div></div>
<div class="phoneBottom"><div class="phoneNavItem"><span class="phoneNavIcon">◆</span>Home</div><div class="phoneNavItem"><span class="phoneNavIcon">♧</span>Friends</div><div class="phoneNavItem"><span class="phoneCreate">+</span></div><div class="phoneNavItem"><span class="phoneNavIcon">□</span>Inbox</div><div class="phoneNavItem"><span class="phoneNavIcon">○</span>Me</div></div>
</div></div><div class="previewHint">Preview is for layout. After rendering, the actual MP4 plays inside the phone.</div>
</aside>
</div>
</div>
</section>
</main><script>
let clips=[],scoutClips=[],selected=[],previewIndex=0,renderedReady=false;const $=id=>document.getElementById(id);function esc(s){return String(s||'').replace(/[&<>\"]/g,m=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;"}[m]))}async function api(url,opt={}){const r=await fetch(url,opt);const j=await r.json().catch(()=>({detail:r.statusText||"Request failed"}));if(!r.ok)throw Error(j.detail||"Request failed");return j}
function showTab(name){const editor=name==='editor';$('clipsPanel').classList.toggle('active',!editor);$('editorPanel').classList.toggle('active',editor);$('clipsTab').classList.toggle('active',!editor);$('editorTab').classList.toggle('active',editor);window.scrollTo({top:0,behavior:'smooth'});if(editor){renderEditor();syncPreview()}}
async function boot(){try{const s=await api('/api/status');$('status').textContent=s.connected?'Twitch connected ✓':'Twitch not connected';$('callback').textContent=s.callback;if(s.connected)$('setup').classList.add('hidden')}catch(e){$('status').textContent='Server error'}const d=new Date();$('phoneTime').textContent=d.toLocaleTimeString([],{hour:'numeric',minute:'2-digit'})}function idx(id){return selected.findIndex(x=>x.id===id)}
function card(c,i,source){const creator=c.broadcaster_name?`<span class="creator">${esc(c.broadcaster_name)}</span> · `:'';const open=c.url?`<a class="btn ghost" target="_blank" rel="noopener" href="${esc(c.url)}">Open Twitch</a>`:'';const on=idx(c.id)>=0;return `<div class="clip ${on?'selected':''}"><div><b>${esc(c.title)}</b><div class="small">${creator}${Number(c.view_count).toLocaleString()} views · ${Number(c.duration).toFixed(1)}s · ${esc(c.reason)}</div></div><div class="score">${c.score}</div><div class="actions row">${open}<button class="${on?'secondary':''}" onclick="toggleSelect('${source}',${i})">${on?'Selected ✓':'Select clip'}</button></div></div>`}function redraw(){if(clips.length)$('clips').innerHTML=clips.map((c,i)=>card(c,i,'mine')).join('');if(scoutClips.length)$('scoutClips').innerHTML=scoutClips.map((c,i)=>card(c,i,'scout')).join('')}
async function scanMine(mode){showTab('clips');$('clips').innerHTML='<p>Scanning…</p>';try{const d=await api('/api/scan',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({mode})});clips=d.clips||[];$('clips').innerHTML=clips.map((c,i)=>card(c,i,'mine')).join('')||'<p>No clips found.</p>'}catch(e){$('clips').innerHTML=`<p class="warn">${esc(e.message)}</p>`}}async function scout(){const raw=$('channels').value.trim();if(!raw){$('scoutClips').innerHTML='<p class="warn">Enter at least one Twitch channel.</p>';return}$('scoutClips').innerHTML='<p>Scanning channels…</p>';try{const d=await api('/api/scout',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({channels:raw})});scoutClips=d.clips||[];$('scoutClips').innerHTML=scoutClips.map((c,i)=>card(c,i,'scout')).join('')||'<p>No recent clips found.</p>'}catch(e){$('scoutClips').innerHTML=`<p class="warn">${esc(e.message)}</p>`}}
function invalidateRender(){renderedReady=false;$('phoneVideo').pause();$('phoneVideo').removeAttribute('src');$('phoneVideo').classList.add('hidden');$('result').classList.add('hidden');$('previewStatus').textContent='Live layout'}
function toggleSelect(source,i){const c=source==='scout'?scoutClips[i]:clips[i],j=idx(c.id);if(j>=0)selected.splice(j,1);else if(selected.length<10)selected.push({...c,trim_start:0,trim_end:Math.min(Number(c.duration)||20,20),overlay:''});else alert('You can use up to 10 clips.');previewIndex=Math.min(previewIndex,Math.max(0,selected.length-1));invalidateRender();renderEditor();redraw()}function clearSelection(){selected=[];previewIndex=0;invalidateRender();renderEditor();redraw()}function moveItem(i,d){const j=i+d;if(j<0||j>=selected.length)return;[selected[i],selected[j]]=[selected[j],selected[i]];previewIndex=j;invalidateRender();renderEditor()}function removeItem(i){selected.splice(i,1);previewIndex=Math.min(previewIndex,Math.max(0,selected.length-1));invalidateRender();renderEditor();redraw()}function setField(i,k,v){selected[i][k]=(k==='trim_start'||k==='trim_end')?Math.max(0,Number(v)||0):v;previewIndex=i;projectChanged()}function previewItem(i){previewIndex=i;syncPreview();renderEditor(false)}function projectChanged(){invalidateRender();syncPreview()}
function syncPreview(){const count=selected.length;if(!count){$('demoCanvas').textContent='SELECT A CLIP';$('demoCanvas').classList.remove('hidden');$('phoneThumb').classList.add('hidden');$('previewHook').classList.add('hidden');$('previewCreator').textContent='@clipforge';$('previewCaption').textContent='Select a clip to preview your Short.';$('previewAudio').textContent='ClipForge';$('trimBadge').textContent='0.0s – 0.0s';$('clipBadge').textContent='0 / 0';return}previewIndex=Math.min(previewIndex,count-1);const c=selected[previewIndex];$('clipBadge').textContent=`${previewIndex+1} / ${count}`;$('trimBadge').textContent=`${Number(c.trim_start||0).toFixed(1)}s – ${Number(c.trim_end||0).toFixed(1)}s`;$('previewCreator').textContent='@'+String(c.broadcaster_name||'creator').replace(/\s+/g,'');$('previewCaption').textContent=c.title||'Untitled clip';$('previewAudio').textContent=c.broadcaster_name||'ClipForge';const hook=($('globalHook').value.trim()||c.overlay||'').trim();$('previewHook').textContent=hook;$('previewHook').classList.toggle('hidden',!hook);if(!renderedReady){$('phoneVideo').classList.add('hidden');if(c.thumbnail_url){$('phoneThumb').src=c.thumbnail_url;$('phoneThumb').classList.remove('hidden');$('demoCanvas').classList.add('hidden')}else{$('phoneThumb').classList.add('hidden');$('demoCanvas').textContent=c.id&&c.id.startsWith('demo')?'DEMO CLIP PREVIEW':'CLIP PREVIEW';$('demoCanvas').classList.remove('hidden')}}}
function renderEditor(doPreview=true){const count=selected.length;$('selectedCount').textContent=`${count} clip${count===1?'':'s'} selected`;$('selectionSummary').textContent=count?`${count} clip${count===1?'':'s'} ready to edit`:'No clips selected';$('tabSelectedCount').textContent=count;$('tabSelectedCount').classList.toggle('hidden',count===0);if(!count){$('editorList').innerHTML='<div class="emptyEditor">No clips selected yet.<br><br><button onclick="showTab(\'clips\')">Go select clips</button></div>';if(doPreview)syncPreview();return}$('editorList').innerHTML=selected.map((c,i)=>`<div class="editorItem ${i===previewIndex?'previewing':''}"><div class="row"><b style="margin-right:auto">${i+1}. ${esc(c.broadcaster_name?c.broadcaster_name+' — ':'')}${esc(c.title)}</b><button class="ghost" onclick="previewItem(${i})">Preview</button><button class="ghost" onclick="moveItem(${i},-1)">↑</button><button class="ghost" onclick="moveItem(${i},1)">↓</button><button class="danger" onclick="removeItem(${i})">Remove</button></div><div class="grid"><label>Trim start<input type="number" min="0" step="0.1" value="${Number(c.trim_start).toFixed(1)}" oninput="setField(${i},'trim_start',this.value)"></label><label>Trim end<input type="number" min="0.1" step="0.1" value="${Number(c.trim_end).toFixed(1)}" oninput="setField(${i},'trim_end',this.value)"></label><label style="grid-column:span 2">Clip text<input type="text" maxlength="55" value="${esc(c.overlay||'')}" placeholder="optional caption" oninput="setField(${i},'overlay',this.value)"></label></div><div class="small">Original: ${Number(c.duration).toFixed(1)}s · ViralScore ${c.score}</div></div>`).join('');if(doPreview)syncPreview()}
async function renderProject(){if(!selected.length){$('renderStatus').textContent='Select at least one clip.';return}$('renderStatus').textContent='Rendering your Short…';$('result').classList.add('hidden');try{const d=await api('/api/project/render',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({hook:$('globalHook').value.trim(),items:selected})});renderedReady=true;$('phoneThumb').classList.add('hidden');$('demoCanvas').classList.add('hidden');$('phoneVideo').src=d.media_url+'?t='+Date.now();$('phoneVideo').classList.remove('hidden');$('downloadBtn').href=d.download_url;$('result').classList.remove('hidden');$('renderStatus').textContent=`Ready ✓ ${d.duration.toFixed(1)}s`;$('previewStatus').textContent='Rendered MP4';syncPreview()}catch(e){$('renderStatus').textContent=e.message}}boot();renderEditor();
</script></body></html>'''